Translate("frFR", "tirisfal-glades", {
	title = "Clairières de Tirisfal",
	aliases = { "Tirisfal" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Clairières de Tirisfal furent jadis le cœur de {link:lordaeron}Lordaeron{/link}. Leurs longues vallées vertes nourrissaient le plus grand des royaumes humains, et sur leur bord oriental se dressait la capitale du royaume. Aujourd'hui, les clairières sont grises. La brume pèse sur des fermes vides, les moulins tournent pour personne, et les corbeaux sont gras. La terre appartient aux {link:forsaken}Réprouvés{/link}, les morts qui se sont éveillés de nouveau à leur propre esprit. Depuis {link:brill}Brill{/link} et {link:undercity}Undercity{/link}, ils la tiennent contre les vivants comme contre les morts.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne donne l'année où les premiers colons vinrent à Tirisfal. Ils venaient d'{link:arathor}Arathor{/link}, au cours des longs siècles qui suivirent les {link:troll-wars}guerres des Trolls{/link}, et ils trouvèrent une terre riche et des forêts paisibles. Leurs fermes devinrent un royaume, et ce royaume prit le nom de {link:lordaeron}Lordaeron{/link}. Aux âges suivants, des familles nobles de l'ancien cœur d'{link:arathi-highlands}Arathi{/link} achetèrent de grands domaines dans les clairières. Les Agamand, qui possédaient les moulins des hauteurs du nord, passaient pour les plus prospères de toutes.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Les {link:forsaken}Réprouvés{/link} de {link:sylvanas-windrunner}Sylvanas Windrunner{/link} règnent sur Tirisfal, mais ils règnent sur une terre en guerre. Le {link:scourge}Fléau{/link} tient encore les {link:agamand-mills}Moulins d'Agamand{/link} et se faufile au-delà de {link:the-bulwark}La Barricade{/link}, le mur qui protège les clairières des {link:eastern-plaguelands}Maleterres{/link} à l'est. La {link:scarlet-crusade}Croisade écarlate{/link} sort de son monastère au nord-est et entretient des tours de guet à travers le pays. Des gnolls pillent les fosses communes pour y prendre des cadavres qui nourriront les armées du roi-liche. Dans la capitale, la {link:royal-apothecary-society}Société royale des apothicaires{/link} travaille à une nouvelle peste, et les gardes de la Mort gardent des prisonniers vivants dans la cave d'une taverne jusqu'à ce que les apothicaires en aient besoin.

De nouveaux troubles sont venus aussi. Il y a peu, la nécropole de {red:naxxramas}Naxxramas{/red} a frappé {link:undercity}Undercity{/link}, et les éclats de son grand cristal gisent encore épars dans les champs près de la capitale en ruine, où le {link:cult-of-the-damned}culte des Damnés{/link} les recherche. Dans les montagnes de l'ouest, un nouvel ordre de paladins réprouvés tient une forteresse à lui. Peu des leurs lui font confiance.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les {link:forsaken}Réprouvés{/link}.{/b} Les gardes de la Mort patrouillent les routes, les exécuteurs donnent les ordres, et les nouveaux relevés s'éveillent chaque jour dans la crypte du Glas.
• {b}Le {link:scourge}Fléau{/link}.{/b} Morts sans esprit, squelettes et nécromanciens infestent encore les moulins, les fermes et les vieilles cryptes.
• {b}La {link:scarlet-crusade}Croisade écarlate{/link}.{/b} Des fanatiques vêtus de rouge qui brûlent tout mort-vivant qu'ils trouvent, qu'il serve le roi-liche ou non.
• {b}Les gnolls Poils-putrides.{/b} Des esclaves du Fléau qui déterrent les morts.
• {b}{link:murlocs}Murlocs{/link} et bêtes.{/b} Les tribus Vile Fin de la côte et des lacs, les sombres molosses, les chauves-souris du crépuscule et les grandes araignées des vallées de l'est.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La peste.{/b} Pendant la {link:third-war}Troisième Guerre{/link}, la peste du {link:cult-of-the-damned}culte des Damnés{/link} balaya les clairières. Des familles entières moururent et se relevèrent dans les rangs du {link:scourge}Fléau{/link}.
• {b}La chute.{/b} Le prince {link:arthas-menethil}Arthas Menethil{/link} assassina son père {link:terenas-menethil}Terenas Menethil{/link} dans sa propre salle du trône. La capitale tomba, et Tirisfal tomba avec elle. Ce fut la {link:fall-of-lordaeron}chute de Lordaeron{/link}.
• {b}Les {link:forsaken}Réprouvés{/link}.{/b} Quand l'emprise du roi-liche faiblit, {link:sylvanas-windrunner}Sylvanas{/link} et ses fidèles se libérèrent et revendiquèrent les ruines de la capitale. En dessous, ils bâtirent {link:undercity}Undercity{/link}.
• {b}La nécropole.{/b} Quand Naxxramas vint contre Undercity, les Réprouvés la combattirent à la surface. L'{link:argent-dawn}Aube d'argent{/link} combattit à leurs côtés, et beaucoup tombèrent.]=],
		},
		{
			title = "Légendes des clairières",
			text = [=[• Les {link:forsaken}Réprouvés{/link} disent que les gardiens de la crypte du Glas étaient prêts à brûler bon nombre des nouveaux relevés avant qu'ils ne s'éveillent.
• Avant la peste, le peuple solitaire de {link:shadowvale}Shadowvale{/link} brassait un élixir vert à partir d'herbes des collines de l'ouest. Apothicaires, mystiques et empoisonneurs le recherchaient, même après qu'il fut interdit dans la capitale.]=],
		},
	},
})

Translate("frFR", "deathknell", {
	title = "Le Glas",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Glas est un petit village de morts à l'ouest de {link:tirisfal-glades}Tirisfal{/link}. Sa crypte se dresse sur une colline au-dessus d'une chapelle et d'un cimetière. C'est ici que les {link:forsaken}Réprouvés{/link} apportent les corps qu'ils trouvent, et c'est ici que beaucoup s'éveillent de l'emprise du roi-liche pour retrouver leur propre esprit. Le croque-mort {link:undertaker-mordo}Mordo{/link} les accueille. Le prêtre de l'ombre {link:shadow-priest-sarvis}Sarvis{/link} leur explique ce qu'ils sont devenus, et l'exécuteur {link:executor-arren}Arren{/link} les met au travail. Le village n'est pas sûr. Des morts sans esprit errent dans ses maisons du nord, des araignées remplissent la mine d'or des Grottes des Tisse-nuit, et la {link:scarlet-crusade}Croisade écarlate{/link} tient un camp au sud-est.]=],
		},
	},
})

Translate("frFR", "brill", {
	title = "Brill",
	sections = {
		{
			title = "Résumé",
			text = [=[Brill est la principale ville des {link:forsaken}Réprouvés{/link} à {link:tirisfal-glades}Tirisfal{/link}, sur la route entre le Glas et {link:undercity}Undercity{/link}. Son hôtel de ville est le siège du magistrat {link:magistrate-sevren}Sevren{/link} et de l'exécuteur {link:executor-zygand}Zygand{/link}, qui commandent les gardes de la Mort des clairières. Son cimetière est entretenu par des apothicaires apprentis, et son auberge, la Taverne des Pendus, possède une cave où des humains et des nains capturés attendent les expériences des apothicaires. Non loin de la ville, les zeppelins de la {link:horde}Horde{/link} s'élèvent de leurs tours, et en ces jours même un maître des paladins réprouvés a sa place à Brill.]=],
		},
	},
})

Translate("frFR", "agamand-mills", {
	title = "Moulins d'Agamand",
	aliases = { "Crypte de la famille Agamand" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Moulins d'Agamand se dressent sur les hauteurs du nord de {link:tirisfal-glades}Tirisfal{/link}. Ils faisaient la richesse de la famille Agamand, la maison la plus riche des clairières. Quand la peste vint, les Agamand fortifièrent leur demeure et ordonnèrent à leurs ouvriers de rester et de combattre. Tous moururent, et tous se relevèrent. Aujourd'hui, les moulins sont le plus fort avant-poste du {link:scourge}Fléau{/link} à Tirisfal. À leur extrémité nord se trouve la Crypte de la famille Agamand, où un capitaine squelette nommé Dargol a relevé les ancêtres de la famille pour qu'ils combattent pour le roi-liche.]=],
		},
	},
})

Translate("frFR", "solliden-farmstead", {
	title = "Ferme des Solliden",
	aliases = { "Solliden" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Ferme des Solliden s'étend dans l'ouest de {link:tirisfal-glades}Tirisfal{/link}, au nord du Glas. C'est l'un des derniers endroits des clairières où des humains vivants travaillent encore les champs. Les citrouilles poussent encore, et les fermiers rentrent encore leur récolte, car la {link:scarlet-crusade}Croisade écarlate{/link} les protège depuis une tour à l'ouest. Les {link:forsaken}Réprouvés{/link} haïssent la ferme pour sa vie. Les apothicaires de {link:brill}Brill{/link} trouvent tout de même un usage à ses citrouilles. Sur les escarpements au nord-ouest s'élève {link:bandarion-keep}Bandarion Keep{/link}.]=],
		},
	},
})

Translate("frFR", "garren-s-haunt", {
	title = "Antre de Garren",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Antre de Garren est une ferme au nord de {link:tirisfal-glades}Tirisfal{/link}, avec un corps de ferme, une grange et de vastes champs gris. Aucune chronique ne dit qui était Garren. Les gnolls Poils-putrides tiennent aujourd'hui la ferme. Ils servent le {link:scourge}Fléau{/link} et pillent les fosses communes au sud-ouest, où furent enterrés les morts de la première peste. Leur chef est un {link:gnolls}gnoll{/link} appelé Maggot Eye, et la ville de {link:brill}Brill{/link} l'a condamné à mort pour ses crimes contre les {link:forsaken}Réprouvés{/link}. L'exécuteur {link:executor-zygand}Zygand{/link} a promis une récompense à qui exécutera la sentence et rapportera sa patte.]=],
		},
	},
})

Translate("frFR", "venomweb-vale", {
	title = "Vallée de Tissevenin",
	sections = {
		{
			title = "Résumé",
			text = [=[La Vallée de Tissevenin est une large vallée à l'extrême est de {link:tirisfal-glades}Tirisfal{/link}, au pied des hauteurs du {link:scarlet-monastery}Monastère écarlate{/link}. Ses bois sont épais de toiles. Les grandes araignées qui y nichent portent un venin qui, selon les apothicaires de {link:brill}Brill{/link}, conserva jadis une peste ancienne. Depuis peu, les gardes de la Mort ont aussi vu une abomination errante rôder près de la vallée. Une telle créature n'aurait pas dû passer {link:the-bulwark}La Barricade{/link} sans être remarquée, et les gardes de la Mort taisent l'affaire. Au bord nord de la vallée, la {link:scarlet-crusade}Croisade écarlate{/link} tient un camp à elle.]=],
		},
	},
})

Translate("frFR", "scarlet-watch-post", {
	title = "Poste de garde de la Croisade",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Poste de garde de la Croisade est une tour de la {link:scarlet-crusade}Croisade écarlate{/link} au nord-est de {link:tirisfal-glades}Tirisfal{/link}, au-delà du Repos de Faol. Il surveille les approches nord du {link:scarlet-monastery}Monastère écarlate{/link}. Son commandant, le capitaine Melrache, est connu des {link:forsaken}Réprouvés{/link} comme un homme impitoyable, et il ne va jamais sans ses deux gardes du corps. La tour est l'une des nombreuses que la Croisade entretient à travers les clairières. De chacune d'elles, ses patrouilles partent brûler les morts. Le capitaine Perrine tient une tour en ruine au sud-ouest de {link:brill}Brill{/link}, et le capitaine Vachon une autre au sud-est, près de la Ferme des Balnir.]=],
		},
	},
})

Translate("frFR", "brightwater-lake", {
	title = "Lac Etincelant",
	aliases = { "Retraite de Gunther" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac Etincelant est le plus grand lac de {link:tirisfal-glades}Tirisfal{/link}, au nord-est de {link:brill}Brill{/link}. Sur une île en son centre se dresse la Retraite de Gunther, le camp d'une liche nommée {link:gunther-arcanus}Gunther Arcanus{/link}. Il est libre du roi-liche, mais il a longtemps cru être le seul, et ses serviteurs attaquaient tous ceux qui approchaient. Au large de la rive sud de l'île se dresse un vieil autel ensanglanté. L'agent du {link:scourge}Fléau{/link} {link:lillith-nefara}Lillith Nefara{/link} y dort jusqu'à ce qu'une bougie d'appel la réveille.]=],
		},
	},
})

Translate("frFR", "capital-city", {
	title = "Capital City",
	aliases = { "Cité de Lordaeron" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les ruines de Capital City se dressent au bord oriental de {link:tirisfal-glades}Tirisfal{/link}. Pendant des siècles, ce fut le siège des rois de {link:lordaeron}Lordaeron{/link}. C'est ici que le prince {link:arthas-menethil}Arthas Menethil{/link} revint de Norfendre et tua son père sur son trône. La cité fut mise à sac et laissée en ruine. Ses murs brisés et sa salle du trône vide gardent aujourd'hui le chemin qui descend vers {link:undercity}Undercity{/link}, la cité des {link:forsaken}Réprouvés{/link} qui s'étend en dessous. Certaines parties des vieilles rues ne sont toujours pas à eux. Des forces du {link:scourge}Fléau{/link} s'attardent dans les ruines de l'est, et les Réprouvés se battent pour les reprendre.]=],
		},
	},
})

Translate("frFR", "whispering-forest", {
	title = "Whispering Forest",
	sections = {
		{
			title = "Résumé",
			text = [=[La Whispering Forest s'étend dans les montagnes de l'ouest de {link:tirisfal-glades}Tirisfal{/link}, au pied de la falaise appelée {link:bandarion-keep}Northface Rock{/link}. Ses bois sont sombres, et l'on dit que ses racines plongent profond. Certains à {link:undercity}Undercity{/link} disent que la forêt est touchée par le Vide, et que des choses rampent sous elle qui ne le devraient pas. Des cerfs et des biches malades errent dans ses clairières. Près d'un cercle de grands champignons marche un chevalier spectral lié là par un serment. Au sud-ouest se trouvent les ruines de {link:shadowvale}Shadowvale{/link}, et au-dessus de tout se dresse Bandarion Keep.]=],
		},
	},
})

Translate("frFR", "bandarion-keep", {
	title = "Bandarion Keep",
	aliases = { "Northface Rock" },
	sections = {
		{
			title = "Résumé",
			text = [=[Bandarion Keep est le monastère de {link:tyr-s-watch}Tyr's Watch{/link}, l'ordre des paladins réprouvés. Il se dresse sur Northface Rock, l'escarpement abrupt entre la {link:whispering-forest}Whispering Forest{/link} et le reste de {link:tirisfal-glades}Tirisfal{/link}. Pendant la dernière guerre, l'{link:argent-dawn}Aube d'argent{/link} le tint contre le {link:scourge}Fléau{/link}. Quand l'Aube se retira dans les {link:eastern-plaguelands}Maleterres{/link}, la forteresse tomba en ruine, et les murlocs Vile Fin en firent un lieu de frai. {link:danitha-morr}Danitha Morr{/link} et ses paladins les en chassèrent et commencèrent à rebâtir. Elle donna au donjon le nom de {link:garek-bandarion}Garek Bandarion{/link}, le premier des {link:forsaken}Réprouvés{/link} à reprendre la {link:holy-light}Lumière sacrée{/link}.]=],
		},
	},
})

Translate("frFR", "shadowvale", {
	title = "Shadowvale",
	sections = {
		{
			title = "Résumé",
			text = [=[Shadowvale est un village en ruine au fond de la {link:whispering-forest}Whispering Forest{/link}, au sud-ouest de {link:bandarion-keep}Bandarion Keep{/link}. Ses habitants étaient étranges et secrets de leur vivant, et ils n'accueillaient pas les visiteurs. Aujourd'hui, le village appartient aux Ternis, des paladins relevés qui tournent la Lumière contre leur propre peuple. Des morts sans esprit se rassemblent dans les caves sous le village. On dit qu'un cultiste y a porté un éclat du cristal de la nécropole, et quoi qu'il fasse, il rend les morts plus forts ou plus nombreux.]=],
		},
	},
})

Translate("frFR", "tyr-s-watch", {
	title = "Tyr's Watch",
	sections = {
		{
			title = "Résumé",
			text = [=[Tyr's Watch est un ordre de paladins {link:forsaken}réprouvés{/link}, fondé depuis peu dans les {link:tirisfal-glades}Clairières de Tirisfal{/link}. Ses membres étaient de leur vivant des serviteurs de la {link:holy-light}Lumière sacrée{/link}. Ils moururent, se relevèrent, et découvrirent que la Lumière leur répondait encore, bien que son contact brûle désormais leur chair. Ils ont leur monastère à {link:bandarion-keep}Bandarion Keep{/link}, et {link:danitha-morr}Danitha Morr{/link} les dirige.]=],
		},
		{
			title = "Croyances",
			text = [=[Les paladins de Tyr's Watch enseignent que la douleur n'est pas une raison de se détourner de la Lumière. Soigner les blesse, alors ils apprennent à soigner à travers la douleur, et ils appellent cela un creuset. Ils enseignent que la recherche du bien pour lui-même est le cœur de leur vocation. Ils vont chercher les misérables et les oubliés d'{link:undercity}Undercity{/link} et les aident de petites manières, car ils croient que les petits actes aussi les lient à la Lumière.]=],
		},
		{
			title = "L'ordre et son peuple",
			text = [=[Les {link:forsaken}Réprouvés{/link} se souviennent bien de ce que les vivants leur firent au nom de la Lumière. Beaucoup craignent qu'un paladin ne les frappe un jour comme des monstres. Certains paladins relevés font exactement cela. L'ordre les appelle les Ternis, et il les traque. La Dame noire elle-même se méfie de Tyr's Watch et a dit à ses paladins qu'elle les surveille. {link:danitha-morr}Danitha{/link} croit qu'il faudra peut-être des années, ou des décennies, avant que son ordre ne gagne une pleine confiance. Elle compte bien gagner cette confiance malgré tout.]=],
		},
	},
})

Translate("frFR", "shadow-priest-sarvis", {
	title = "Prêtre de l'ombre Sarvis",
	subtitle = "Prêtre du Glas",
	found = "La chapelle du Glas",
	hint = "Parlez au prêtre de l'ombre dans la chapelle du Glas.",
	allegiance = "Réprouvés",
	aliases = { "Sarvis" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le prêtre de l'ombre Sarvis tient la chapelle au pied de la colline du Glas. Quand les nouveaux relevés sortent de la crypte en titubant, glacés et confus, c'est Sarvis qui leur dit la vérité. Ils sont morts. Ils sont libres du roi-liche. Et ils appartiennent désormais à {link:sylvanas-windrunner}la Dame noire{/link}, qui mène les {link:forsaken}Réprouvés{/link} dans leur guerre contre le {link:scourge}Fléau{/link} et contre les humains qui les traquent.]=],
		},
		{
			title = "Importance",
			text = [=[Sarvis donne aux nouveaux {link:forsaken}Réprouvés{/link} leur premier but. Il les envoie contre les morts sans esprit du village, les anciens frères et sœurs qui n'ont pu être ramenés au bercail.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il accueille les relevés qui s'éveillent dans la crypte du Glas.
• Il les envoie détruire les zombies sans esprit et les squelettes Rattlecage.]=],
		},
	},
	mentions = {
		{ text = "Un réveil brutal" },
		{ text = "Les sans-esprit" },
		{ text = "Secouer les Rattlecage" },
	},
	bonds = {
		{ id = "undertaker-mordo", name = "Croque-mort Mordo", note = "lui envoie les relevés" },
		{ id = "executor-arren", name = "Exécuteur Arren", note = "commande le Glas" },
	},
})

Translate("frFR", "undertaker-mordo", {
	title = "Croque-mort Mordo",
	subtitle = "Gardien de la crypte",
	found = "Devant la crypte du Glas",
	hint = "Parlez au croque-mort qui attend devant la crypte du Glas.",
	allegiance = "Réprouvés",
	aliases = { "Mordo" },
	sections = {
		{
			title = "Résumé",
			text = [=[Mordo est le croque-mort du Glas et le gardien de sa crypte. Il est souvent le premier visage que voit un nouveau Réprouvé. Il ne prétend pas que l'éveil est doux. Les corps qui ne bougent pas sont brûlés, et il dit sans détour que beaucoup de ceux qui se relèvent ont bien failli partir au feu avec eux.]=],
		},
		{
			title = "Importance",
			text = [=[Mordo se tient au seuil de la seconde vie des {link:forsaken}Réprouvés{/link}. Tous ceux qui s'éveillent au Glas passent entre ses mains, et il les envoie chacun à la chapelle en contrebas.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il garde la crypte du Glas et prend soin des morts qu'on y apporte.
• Il envoie les nouveaux relevés au prêtre de l'ombre {link:shadow-priest-sarvis}Sarvis{/link}.]=],
		},
	},
	mentions = {
		{ text = "Un réveil brutal" },
	},
	bonds = {
		{ id = "shadow-priest-sarvis", name = "Prêtre de l'ombre Sarvis", note = "reçoit les relevés" },
	},
})

Translate("frFR", "executor-arren", {
	title = "Exécuteur Arren",
	subtitle = "Exécuteur du Glas",
	found = "Le Glas",
	hint = "Parlez à l'exécuteur qui commande le Glas.",
	allegiance = "Réprouvés · Gardes de la Mort",
	aliases = { "Arren" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'exécuteur Arren commande le Glas. Il a peu de soldats et beaucoup de soucis. Des araignées ont envahi la mine d'or dont son peuple a besoin, et un camp de la {link:scarlet-crusade}Croisade écarlate{/link} a surgi au sud-est. Il rend compte à l'exécuteur {link:executor-zygand}Zygand{/link}, à {link:brill}Brill{/link}, et il envoie chaque recrue capable régler ce que ses gardes de la Mort ne peuvent régler.]=],
		},
		{
			title = "Importance",
