Translate("frFR", "garek-bandarion", {
	title = "Garek Bandarion",
	subtitle = "Le premier paladin réprouvé",
	found = "Son souvenir demeure à Bandarion Keep",
	hint = [=[Cherchez le donjon des collines de l'ouest qui porte son nom.]=],
	allegiance = [=[Réprouvés · Gardes de la Mort · autrefois la garde de la cité de Lordaeron]=],
	aliases = { "Garek", "Capitaine Bandarion" },
	sections = {
		{
			title = "Résumé",
			text = [=[Garek Bandarion était un soldat de {link:lordaeron}Lordaeron{/link} qui mourut lors de sa chute et se releva parmi les {link:forsaken}Réprouvés{/link}. Il devint le premier capitaine des gardes de la Mort, et il fut le premier des Réprouvés à reprendre la {link:holy-light}Lumière sacrée{/link} en tant que paladin. Il tomba quand la nécropole de {red:naxxramas}Naxxramas{/red} vint contre {link:undercity}Undercity{/link}. Les paladins de {link:tyr-s-watch}Tyr's Watch{/link} donnèrent son nom à leur monastère, et ils crient encore son nom au combat.]=],
		},
		{
			title = "Importance",
			text = [=[Pour les paladins réprouvés, Garek est la preuve que la Lumière ne les abandonna pas dans la mort. Pour les gardes de la Mort, il est le capitaine qui bâtit leurs rangs. Sa vie relie les derniers jours du royaume des vivants aux premiers jours de celui des morts.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• De son vivant, il servit dans la garde de la capitale sous les ordres du capitaine Landen, qui le choisit pour successeur.
• Le jour où {link:arthas-menethil}Arthas{/link} assassina son père, Landen et lui firent sortir des survivants par les égouts sous la cité.
• Il se vengea du baron Rivendare, le seigneur qui trahit le royaume au profit du {link:cult-of-the-damned}culte des Damnés{/link}, et mourut de ses blessures et de la peste.
• En tant que Réprouvé, il combattit aux côtés de la forestière noire {link:dark-ranger-anya}Anya{/link} aux premiers jours d'{link:undercity}Undercity{/link}.
• Il s'éleva jusqu'au rang de capitaine des gardes de la Mort.
• Il mourut en défendant Undercity contre Naxxramas.]=],
		},
	},
	chapters = {
		{
			title = "Les derniers jours de Lordaeron",
			hint = [=[Découvrez ce que les Réprouvés d'Undercity disent de leur premier capitaine.]=],
			text = [=[Garek était un jeune garde qui brûlait de combattre, et son capitaine, Landen, lui disait que protéger le peuple était la plus grande gloire. La nuit où {link:arthas-menethil}Arthas{/link} tua le roi {link:terenas-menethil}Terenas Menethil{/link}, ils trouvèrent la salle du trône pleine de cultistes. {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link} les envoya sauver qui ils pourraient. Sous la cité, ils découvrirent que le culte était prêt depuis longtemps. Landen resta en arrière pour retenir le baron Rivendare afin que Garek puisse mener le peuple en lieu sûr. Garek ne pardonna jamais au baron. Il le traqua jusqu'à Stratholme et l'y tua, et il mourut de ses blessures.]=],
		},
		{
			title = "Une seconde vie",
			hint = [=[Écoutez les paladins de Bandarion Keep parler de leur fondateur.]=],
			text = [=[Garek s'éveilla dans les caveaux d'{link:undercity}Undercity{/link} sans autre souvenir que son nom. L'apothicaire Putress voulait se servir de son corps comme pièces détachées. La forestière noire {link:dark-ranger-anya}Anya{/link} l'en empêcha. Garek jura fidélité à {link:sylvanas-windrunner}Sylvanas{/link}, et avec Anya il rassembla dans les ruines les morts au libre arbitre, dégagea les tunnels et aida la cité à grandir. Quand la {link:scarlet-crusade}Croisade écarlate{/link} perça les murs d'Undercity, il mena les gardes de la Mort contre elle. Au cours de ces années, la Lumière se mit à lui répondre de nouveau.]=],
		},
		{
			title = "Le donjon de son nom",
			hint = [=[Découvrez pourquoi la forteresse de Northface Rock porte son nom.]=],
			text = [=[Quand Naxxramas vint sur les ruines de la capitale, les {link:forsaken}Réprouvés{/link} et l'{link:argent-dawn}Aube d'argent{/link} la combattirent ensemble à la surface. Garek ne revint pas. {link:danitha-morr}Danitha Morr{/link} et {link:leonid-barthalomew}Leonid Barthalomew{/link} combattirent dans cette bataille et y perdirent de nombreux amis. Quand Danitha prit pour son ordre la vieille forteresse de {link:bandarion-keep}Northface Rock{/link}, elle lui donna son nom.]=],
		},
	},
	mentions = {
		{ text = "Une juste cause" },
		{ text = "{link:bandarion-keep}Bandarion Keep{/link}" },
		{ text = "La justice de la Lumière" },
	},
	bonds = {
		{ id = "dark-ranger-anya", name = "Forestière noire Anya", note = "sa compagne d'armes" },
		{ id = "danitha-morr", name = "Danitha Morr", note = "a donné son nom au donjon" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "un ami" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "sa reine" },
	},
})

Translate("frFR", "dark-ranger-anya", {
	title = "Forestière noire Anya",
	subtitle = "Forestière noire de la reine des banshees",
	found = "Inconnu en ces jours",
	hint = "Découvrez-la à travers les récits sur Garek Bandarion.",
	allegiance = "Réprouvés · autrefois les Farstriders de Quel'Thalas",
	aliases = { "Anya" },
	sections = {
		{
			title = "Résumé",
			text = [=[Anya est une forestière noire, l'une des elfes morts-vivants qui servent {link:sylvanas-windrunner}Sylvanas Windrunner{/link}. De son vivant, elle était une forestière de {link:quel-thalas}Quel'Thalas{/link} sous le commandement de Sylvanas. Elle mourut en défendant sa patrie contre le {link:scourge}Fléau{/link} et se releva en esclave de celui-ci. Elle se souvient de tout ce qu'elle fit en ce temps-là. Quand elle se libéra, Sylvanas lui donna un lieu auquel appartenir, et pour cela Anya donna à la Dame noire sa loyauté pour toujours.]=],
		},
		{
			title = "Importance",
			text = [=[Anya est l'une des premières forestières noires des {link:forsaken}Réprouvés{/link}, et l'une de celles qui virent {link:undercity}Undercity{/link} surgir des tunnels. Elle fut la compagne d'armes de {link:garek-bandarion}Garek Bandarion{/link} au cours des premières guerres du royaume des morts. Là où il avait perdu ses souvenirs, elle avait gardé tous les siens, et elle lui apprit que pour beaucoup de Réprouvés, la mort est une page blanche et une seconde vie. Elle se fie très peu aux vivants. Quand un paladin de l'ancienne Main d'argent fit preuve de pitié envers un ouvrier réprouvé et que son capitaine tua l'homme malgré tout, Anya dit à Garek que les vivants ne verraient jamais les morts-vivants comme des personnes, et qu'on ne pouvait leur faire confiance.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle tomba en défendant {link:quel-thalas}Quel'Thalas{/link}, et commit des actes terribles en esclave du roi-liche.
• Elle empêcha l'apothicaire Putress de découper {link:garek-bandarion}Garek{/link} en pièces détachées à son éveil.
• Elle dit à Garek que sa mémoire perdue était une grâce, car elle-même ne se souvenait que trop bien de ses propres crimes.
• Avec Garek, elle sauva des ruines de la capitale les morts au libre arbitre.
• Elle combattit à ses côtés contre la {link:scarlet-crusade}Croisade écarlate{/link} et contre Naxxramas.
• Avec {link:sylvanas-windrunner}Sylvanas{/link} et la forestière noire Clea, elle chevaucha jusqu'à la ferme des {link:marshal-marris}Marris{/link} à la recherche de {link:nathanos-blightcaller}Nathanos Marris{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne dit où Anya sert aujourd'hui, ni ce qu'elle fit après la chute de {link:garek-bandarion}Garek{/link}.]=],
		},
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "son compagnon d'armes" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "sa reine" },
	},
})

Translate("frFR", "danitha-morr", {
	title = "Danitha Morr",
	subtitle = "Commandante de Bandarion Keep",
	found = "Bandarion Keep",
	hint = "Parlez à la meneuse des paladins de Bandarion Keep.",
	allegiance = "Tyr's Watch · Réprouvés",
	aliases = { "Danitha" },
	sections = {
		{
			title = "Résumé",
			text = [=[Danitha Morr dirige les paladins de {link:tyr-s-watch}Tyr's Watch{/link} depuis {link:bandarion-keep}Bandarion Keep{/link}. Elle se dit ce qui ressemble le plus à un commandant au donjon. Elle combattit pour défendre {link:undercity}Undercity{/link} quand Naxxramas vint, et elle y perdit des amis, dont {link:garek-bandarion}Garek Bandarion{/link}. Quand elle prit la forteresse en ruine de Northface Rock, elle lui donna son nom.]=],
		},
		{
			title = "Importance",
			text = [=[Danitha tente ce qu'aucun Réprouvé n'a fait avant elle : bâtir un ordre de la {link:holy-light}Lumière sacrée{/link} parmi les morts et lui gagner une place dans leur royaume. Son peuple craint les paladins. Sa reine se méfie d'eux. Elle croit que l'œuvre prendra peut-être des décennies, et elle l'accomplit malgré tout.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle rebâtit {link:bandarion-keep}Bandarion Keep{/link} avec des matériaux récupérés dans les ruines de {link:shadowvale}Shadowvale{/link}.
• Elle traque les Ternis, les paladins relevés qui tournent leurs lames contre les {link:forsaken}Réprouvés{/link}.
• Elle envoie ses paladins aider les pauvres d'{link:undercity}Undercity{/link}.
• Elle envoie son ordre dans les {link:silverpine-forest}Pins argentés{/link} pour gagner la confiance de la {link:horde}Horde{/link}.]=],
		},
		{ title = "Non consigné", text = "On a peu écrit sur la vie de Danitha avant sa mort." },
	},
	chapters = {
		{
			title = "Un foyer dans les collines",
			hint = [=[Trouvez le chemin de Bandarion Keep et rencontrez sa commandante.]=],
			text = [=[Le donjon était en ruine quand les paladins de Danitha arrivèrent. Des murlocs Vile Fin en avaient fait un lieu de frai, et ils se battirent pour le reprendre même après en avoir été chassés. Danitha avait peu de matériaux, moins d'alliés encore et une foule de murs à réparer. Elle accueillait chaque nouveau venu qui restait fidèle à la Lumière.]=],
		},
		{
			title = "Les Ternis",
			hint = [=[Occupez-vous des paladins relevés qui ont fait de Shadowvale leur repaire.]=],
			text = [=[Tous les paladins qui se relèvent ne peuvent accepter ce qu'ils sont devenus. Certains gardent les haines de leur ancienne vie et tuent les {link:forsaken}Réprouvés{/link} qu'ils rencontrent. Chacun de ces meurtres permet plus facilement aux ennemis de l'ordre d'attiser la peur. Danitha fit détruire les Ternis de {link:shadowvale}Shadowvale{/link} et décapiter leur commandant, {link:rudolph-gelhardt}Rudolph Gelhardt{/link}.]=],
		},
		{
			title = "Un gage de bonne foi",
			hint = "Portez le présent de Danitha à la Dame noire.",
			text = [=[Danitha envoya la tête de {link:rudolph-gelhardt}Gelhardt{/link} à {link:undercity}Undercity{/link}, pour montrer à {link:sylvanas-windrunner}la Dame noire{/link} que {link:tyr-s-watch}Tyr's Watch{/link} fait elle-même régner l'ordre chez elle. Sylvanas ne douta pas de la sincérité de Danitha. Elle dit qu'elle s'attendait à ce que d'autres paladins perdent la raison, et qu'elle pourrait un jour décider de ne plus tolérer l'ordre. Elle dit à ses paladins de bien servir, et qu'elle les surveillerait.]=],
		},
	},
	mentions = {
		{ text = "La visite des lieux" },
		{ text = "Les Ternis" },
		{ text = "Un gage de bonne foi" },
		{ text = "Une leçon de divinité" },
		{ text = "Incident diplomatique" },
		{ text = "Une juste cause" },
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "un ami tombé" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "un vieux camarade" },
		{ id = "rudolph-gelhardt", name = "Rudolph Gelhardt", note = "le commandant des Ternis" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "se méfie de son ordre" },
	},
})

Translate("frFR", "leonid-barthalomew", {
	title = "Leonid Barthalomew",
	subtitle = "Émissaire de l'Aube d'argent",
	found = "Bandarion Keep",
