		},
		{
			title = "Hauts faits",
			text = [=[• Il combattit le {link:scourge}Fléau{/link} pour défendre {link:undercity}Undercity{/link}.
• Il envoie une lettre à un vieil ami, le gobelin {link:glix-xizzix}Glix Xizzix{/link} d'Undercity.]=],
		},
	},
	mentions = {
		{ text = "Une juste cause" },
		{ text = "{link:bandarion-keep}Bandarion Keep{/link}" },
